423	func runFactsPromote(cmd *cobra.Command, opts Options, brainDir, from, into, strategy string, jsonOut bool) error {
424		now := opts.Now().UTC()
425		var promoted, proposalCount int
426		if err := brainstore.WithBrainWriteLock(brainDir, func() error {
427			source, err := factstore.Load(brainDir, from)
428			if err != nil {
429				return err
430			}
431			target, err := factstore.Load(brainDir, into)
432			if err != nil {
433				return err
434			}
435			merged, proposals, promotedCount := promoteFacts(source, target, strategy, into, now)
436			promoted = promotedCount
437			proposalCount = len(proposals)
438			if err := factstore.Write(brainDir, into, merged); err != nil {
439				return err
440			}
441			if len(proposals) > 0 {
442				existing, _ := loadFactProposals(brainDir, into)
443				if err := writeFactProposals(brainDir, into, dedupeProposals(append(existing, proposals...))); err != nil {
444					return err
445				}
446			}
447			return updateFactSourceManifestLocked(brainDir, now)
448		}); err != nil {
449			return err
450		}
451		summary := map[string]any{"from": from, "into": into, "strategy": strategy, "promoted": promoted, "proposals": proposalCount}
452		if jsonOut {
453			return cmdutil.WriteJSON(cmd, summary)
454		}
455		fmt.Fprintf(cmd.OutOrStdout(), "promoted %d memory(ies) from %s into %s (%s); %d conflict(s) queued for review\n", promoted, from, into, strategy, proposalCount)
456		return nil
457	}
