461	func newFactsGCCommand(opts Options) *cobra.Command {
462		var (
463			branch  string
464			force   bool
465			retain  time.Duration
466			jsonOut bool
467			global  bool
468		)
469		cmd := &cobra.Command{
470			Use:   "gc",
471			Short: "Prune retracted and old superseded memories; report orphans",
472			Args:  cobra.NoArgs,
473			RunE: func(cmd *cobra.Command, args []string) error {
474				var (
475					brainDir       string
476					resolvedBranch string
477					err            error
478				)
479				// Without this the global store is write-only in one direction:
480				// facts can be retracted there and never pruned, so it grows
481				// without bound and the documented promise that global facts get
482				// the same lifecycle as repository ones is not kept.
483				if global {
484					if strings.TrimSpace(branch) != "" {
485						return fmt.Errorf("--global and --branch cannot be combined: a global memory is not on a branch")
486					}
487					brainDir, resolvedBranch, err = factstore.ResolveGlobalTarget(opts.Env)
488				} else {
489					_, brainDir, resolvedBranch, err = resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
490				}
491				if err != nil {
492					return err
493				}
494				return runFactsGC(cmd, opts, brainDir, resolvedBranch, force, retain, jsonOut)
495			},
496		}
497		cmd.Flags().BoolVar(&global, "global", false, "Prune the global memory store rather than this repository's")
498		cmd.Flags().StringVar(&branch, "branch", "", "Branch to gc (default: current branch)")
499		cmd.Flags().BoolVar(&force, "force", false, "Actually prune (default: dry-run reporting what would be pruned)")

