22	// updateFactSourceManifest recomputes sources.facts from the whole on-disk fact
23	// store and writes it back. Commands that mutate facts outside the distill
24	// pipeline (remember, facts review/promote/gc) call this so `status` and the
25	// manifest stay accurate. Chunk counts are preserved from the existing source
26	// (they describe the last distill run, not these edits).
27	func updateFactSourceManifest(brainDir string, now time.Time) error {
28		return brainstore.WithBrainWriteLock(brainDir, func() error {
29			return updateFactSourceManifestLocked(brainDir, now)
30		})
31	}
32	
33	// reclassifyAllFactBranches backfills the deterministic KIND/LOCUS onto every
34	// fact store (non-destructive: only fills facts missing a valid kind, while
35	// locus is always reconciled), collapses records that repeat an id within one
36	// file, and rebuilds the fact source manifest so by_kind stays accurate. No
37	// agent, no tokens. A no-op when no facts exist. Returns the number of facts
38	// changed (reclassified plus duplicates folded). Holds the brain write lock
39	// for the whole pass.
40	//
41	// This runs from `refresh` so a kind never goes stale: facts distilled before
42	// kind-storage, or any fact left without a valid kind, are repaired on the next
43	// refresh rather than needing a manual `facts reclassify`.
44	//
45	// The pass iterates store FILES, never record-branch buckets. An earlier
46	// version wrote factstore.LoadAllBranches buckets back through factstore.Write, and a
47	// bucket spans files: every main-stamped record the hosted pull had mirrored
48	// into a feature branch's store was concatenated into main's file, roughly
49	// doubling it on each refresh (COR-2220). The per-file dedup below is also the
50	// repair for stores that doubling already damaged — the copies carry the same
51	// id, so folding them through Upsert's merge rules loses nothing.
52	func reclassifyAllFactBranches(brainDir string, now time.Time) (int, error) {
53		changed := 0
54		err := brainstore.WithBrainWriteLock(brainDir, func() error {
55			byFile, err := factstore.LoadStoreFiles(brainDir)
56			if err != nil {
57				return err
58			}
59			if len(byFile) == 0 {
60				return nil
61			}
62			for dirName, facts := range byFile {
63				deduped, folded := dedupFactRecords(facts)
64				c := factstore.Reclassify(deduped, false)
65				if c == 0 && folded == 0 {
66					continue
67				}
68				if err := factstore.WriteStoreFile(brainDir, dirName, deduped); err != nil {
69					return err
70				}
71				changed += c + folded
72			}
73			// Refresh upgrades even an unchanged legacy store. Ordinary read
74			// commands remain read-only, including on read-only installations.
75			if err := factstore.MigrateRepository(brainDir); err != nil {
76				return err
77			}
78			return updateFactSourceManifestLocked(brainDir, now)
79		})
80		return changed, err
81	}
82	
83	func updateFactSourceManifestLocked(brainDir string, now time.Time) error {
84		byBranch, err := factstore.LoadAllBranches(brainDir)
85		if err != nil {
86			return err
87		}
88		branches := make([]string, 0, len(byBranch))
89		for branch := range byBranch {
90			branches = append(branches, branch)
91		}
92		proposals := countFactProposals(brainDir, branches)
93	
94		manifest, err := bmanifest.Load(brainDir)
95		if err != nil {
96			return err
97		}
98		var previous *factSourceManifest
99		if manifest.Sources != nil && manifest.Sources.Facts != nil {
100			previous = manifest.Sources.Facts
101		}
102		source := factstore.SummarizeSource(now, byBranch, 0, 0, proposals, nil)
103		preserveFactDistillEvidence(source, previous)
104		if manifest.Sources == nil {
105			manifest.Sources = &brainSources{}
106		}
107		manifest.Sources.Facts = source
108		if manifest.GeneratedAt.IsZero() {
109			manifest.GeneratedAt = now
110		}
111		return writeBrainManifestAndReadme(brainDir, *manifest)
112	}
113	
114	func preserveFactDistillEvidence(source, previous *factSourceManifest) {
115		if source == nil || previous == nil {
116			return
117		}
118		source.LastDistilledAt = previous.LastDistilledAt
119		if previous.TokenUsage != nil {
120			usage := *previous.TokenUsage
121			source.TokenUsage = &usage
122		}
123		source.ChunksScanned = previous.ChunksScanned
124		source.ChunksDistilled = previous.ChunksDistilled
125		source.CacheHits = previous.CacheHits
126		source.FailedChunks = previous.FailedChunks
127		source.PreprocessedBytes = previous.PreprocessedBytes
128		source.ExtractionWaitSeconds = previous.ExtractionWaitSeconds
129		source.ReconcileSeconds = previous.ReconcileSeconds
130		source.WriteSeconds = previous.WriteSeconds
131		// The run-configuration and call-count evidence must survive too: facts
132		// admin commands (review/promote/gc) rebuild this summary, and zeroing
133		// these blanks the fields the release audit reads from the manifest.
134		source.Agent = previous.Agent
135		source.Model = previous.Model
136		source.Effort = previous.Effort
137		source.Branch = previous.Branch
138		source.Force = previous.Force
139		source.Jobs = previous.Jobs
140		source.ExtractionJobsCap = previous.ExtractionJobsCap
141		source.MaxChunkBytes = previous.MaxChunkBytes
142		source.Confidence = previous.Confidence
143		source.ExtractionCalls = previous.ExtractionCalls
144		source.ReconcileCalls = previous.ReconcileCalls
145		source.TotalAgentCalls = previous.TotalAgentCalls
146		source.TotalSeconds = previous.TotalSeconds
147		source.Warnings = append([]string(nil), previous.Warnings...)
148	}
