8	// errStaleProposal is returned when a proposal references a fact that no longer
9	// exists or is no longer active.
10	var errStaleProposal = errors.New("proposal references a missing or inactive fact")
11	
12	// removeFactByID returns facts with the record of the given id removed.
13	func removeFactByID(facts []Record, id string) []Record {
14		out := facts[:0:0]
15		for _, f := range facts {
16			if f.ID != id {
17				out = append(out, f)
18			}
19		}
20		return out
21	}
