23	// ApplyProposal resolves a queued proposal by performing its merge/supersede.
24	// Merge consolidates the candidate's provenance into the target and removes the
25	// now-redundant candidate record; supersede marks the target superseded by the
26	// candidate, which stays active. Both records must be distinct and active.
27	func ApplyProposal(facts []Record, p Proposal, now time.Time) ([]Record, error) {
28		ci := IndexOf(facts, p.CandidateID)
29		ti := IndexOf(facts, p.TargetID)
30		if ci < 0 || ti < 0 || facts[ci].Status != StatusActive || facts[ti].Status != StatusActive {
31			return facts, errStaleProposal
32		}
33		if ci == ti {
34			return facts, errors.New("proposal must reference two distinct facts")
35		}
36		if p.Action != ActionMerge && p.Action != ActionSupersede {
37			return facts, errors.New("proposal action must be merge or supersede")
38		}
39		facts = clearConflictLink(facts, p.CandidateID, p.TargetID)
40		ci = IndexOf(facts, p.CandidateID)
41		ti = IndexOf(facts, p.TargetID)
42		if p.Action == ActionMerge {
43			facts[ti].Provenance = UnionAnchors(facts[ti].Provenance, facts[ci].Provenance)
44			facts[ti].UpdatedAt = now
45			return removeFactByID(facts, p.CandidateID), nil
46		}
47		// supersede
48		facts[ti].Status = StatusSuperseded
49		facts[ti].SupersededBy = facts[ci].ID
50		facts[ti].UpdatedAt = now
51		return facts, nil
52	}
