54	// RejectProposal discards a proposal without changing fact status, removing the
55	// conflict cross-link so the pair is no longer flagged as conflicting.
56	func RejectProposal(facts []Record, p Proposal) []Record {
57		return clearConflictLink(facts, p.CandidateID, p.TargetID)
58	}
