60	// clearConflictLink removes the RelatedIDs cross-link between two facts.
61	func clearConflictLink(facts []Record, aID, bID string) []Record {
62		for i := range facts {
63			switch facts[i].ID {
64			case aID:
65				facts[i].RelatedIDs = removeString(facts[i].RelatedIDs, bID)
66			case bID:
67				facts[i].RelatedIDs = removeString(facts[i].RelatedIDs, aID)
68			}
69		}
70		return facts
71	}
