177	// activeConflictIndexes returns indexes of active facts that share a taxonomy
178	// path with candidate but have a different id (a genuine same-path conflict).
179	func activeConflictIndexes(facts []Record, candidate Record) []int {
180		paths := make(map[string]struct{}, len(candidate.Paths))
181		for _, p := range candidate.Paths {
182			paths[p] = struct{}{}
183		}
184		var idx []int
185		for i := range facts {
