199	// GCResult reports the outcome of a garbage-collection pass.
200	type GCResult struct {
201		Kept    []Record
202		Pruned  []Record
203		Orphans []Record // top-level category no longer in the taxonomy; never pruned
204	}
205	
206	// GC prunes retracted facts and superseded facts older than the retention
207	// window, and reports taxonomy-orphaned facts (whose top-level category no
208	// longer exists) without ever deleting them. Orphans that are also prunable
209	// (retracted/old-superseded) are pruned; active orphans are kept and reported.
210	//
211	// Whether a fact's paths are still known is injected via knownTopLevel so the
212	// core stays free of the taxonomy loader: knownTopLevel(path) reports whether
213	// path's top-level category still exists.
214	func GC(facts []Record, knownTopLevel func(path string) bool, now time.Time, retention time.Duration) GCResult {
215		cutoff := now.Add(-retention)
216		var result GCResult
217		for _, f := range facts {
218			if !allPathsKnown(f, knownTopLevel) {
219				result.Orphans = append(result.Orphans, f)
220			}
221			switch f.Status {
222			case StatusRetracted:
223				result.Pruned = append(result.Pruned, f)
224				continue
225			case StatusSuperseded:
226				if f.UpdatedAt.Before(cutoff) {
227					result.Pruned = append(result.Pruned, f)
228					continue
229				}
230			}
231			result.Kept = append(result.Kept, f)
232		}
233		return result
234	}
235	
236	// allPathsKnown reports whether every path's top-level category is known
237	// according to the injected predicate.
238	func allPathsKnown(f Record, knownTopLevel func(path string) bool) bool {
239		for _, p := range f.Paths {
240			if !knownTopLevel(p) {
241				return false
242			}
243		}
244		return true
245	}
