35	// TestFactsPromoteValidatesBothBranchEndpoints is the regression for a promote
36	// that checked --strategy, a missing --from and self-promotion but never once
37	// asked whether the branch names it was handed meant anything.
38	//
39	// Both halves failed silently, and the --into half destroyed data:
40	// factstore.Write creates the target store on demand, so a typo forked the fact set
41	// into a directory keyed to a branch that does not exist. No branch can reach
42	// it, no command names it, and promote reported success — the facts were gone.
43	func TestFactsPromoteValidatesBothBranchEndpoints(t *testing.T) {
44		t.Run("unknown --from is refused", func(t *testing.T) {
45			f, _ := promoteFixtureWithSourceFacts(t)
46			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "no-such-branch", "--strategy", "keep-both")
47			if err == nil {
48				t.Fatalf("promoting from a branch that does not exist succeeded:\n%s", out)
49			}
50			if !strings.Contains(err.Error(), "--from") || !strings.Contains(err.Error(), "no-such-branch") {
51				t.Fatalf("refusal should name --from and the branch, got: %v", err)
52			}
53		})
54	
55		t.Run("unknown --into is refused and strands no store", func(t *testing.T) {
56			f, _ := promoteFixtureWithSourceFacts(t)
57			const bogus = "totally/bogus/branch"
58	
59			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "feature", "--into", bogus, "--strategy", "prefer-target")
60			if err == nil {
61				t.Fatalf("promoting into a branch that does not exist succeeded:\n%s", out)
62			}
63			if !strings.Contains(err.Error(), "--into") || !strings.Contains(err.Error(), bogus) {
64				t.Fatalf("refusal should name --into and the branch, got: %v", err)
65			}
66	
67			// The orphan store is the damage: it must never have been written.
68			if factstore.BranchStoreExists(f.storage.BrainDir, bogus) {
69				t.Fatalf("refused promote still wrote a memory store for %q", bogus)
70			}
71			orphanDir := filepath.Join(f.storage.BrainDir, filepath.FromSlash(factstore.BranchRelDir(bogus)))
72			if _, statErr := os.Stat(orphanDir); statErr == nil {
73				t.Fatalf("refused promote still created the branch directory %s", orphanDir)
74			}
75		})
76	
77		t.Run("a real --from with no facts says so instead of reporting success", func(t *testing.T) {
78			f, _ := promoteFixtureWithSourceFacts(t)
79			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "empty", "--strategy", "keep-both")
80			if err == nil {
81				t.Fatalf("promoting from a branch with no facts reported success:\n%s", out)
82			}
83			if !strings.Contains(err.Error(), "no memories to promote") {
84				t.Fatalf("an empty source should be named as such, got: %v", err)
85			}
86		})
87	
88		t.Run("a valid promote still works", func(t *testing.T) {
89			f, fact := promoteFixtureWithSourceFacts(t)
90			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "feature", "--strategy", "keep-both")
91			if err != nil {
92				t.Fatalf("valid promote was refused: %v\n%s", err, out)
93			}
94			if !strings.Contains(out, "promoted 1 memory(ies) from feature into main") {
95				t.Fatalf("unexpected promote summary:\n%s", out)
96			}
97			facts, loadErr := factstore.Load(f.storage.BrainDir, "main")
98			if loadErr != nil {
99				t.Fatal(loadErr)
100			}
101			if indexOfFact(facts, fact.ID) < 0 {
102				t.Fatalf("promoted fact did not land on main: %+v", facts)
103			}
104		})
105	}
